//! Durable identifiers.
//!
//! All durable IDs are random (v4) UUIDs generated by trusted components.
//! Browser tab/window IDs and process IDs are transient observations and are
//! deliberately not modelled here.

use std::fmt;
use std::str::FromStr;

use serde::{Deserialize, Serialize};
use uuid::Uuid;

macro_rules! uuid_id {
    ($(#[$meta:meta])* $name:ident) => {
        $(#[$meta])*
        #[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
        #[serde(transparent)]
        pub struct $name(Uuid);

        impl $name {
            /// Generates a new random identifier.
            #[must_use]
            pub fn new() -> Self {
                Self(Uuid::new_v4())
            }

            #[must_use]
            pub const fn from_uuid(uuid: Uuid) -> Self {
                Self(uuid)
            }

            #[must_use]
            pub const fn as_uuid(&self) -> &Uuid {
                &self.0
            }
        }

        impl Default for $name {
            fn default() -> Self {
                Self::new()
            }
        }

        impl fmt::Display for $name {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                // Hyphenated lowercase, the stored and wire form.
                fmt::Display::fmt(&self.0.hyphenated(), f)
            }
        }

        impl FromStr for $name {
            type Err = uuid::Error;

            fn from_str(s: &str) -> Result<Self, Self::Err> {
                Uuid::parse_str(s).map(Self)
            }
        }
    };
}

uuid_id!(
    /// A workspace; the first release has a single Default workspace.
    WorkspaceId
);
uuid_id!(
    /// One agent run, from start to clean or unclean exit.
    SessionId
);
uuid_id!(
    /// An immutable committed checkpoint.
    CheckpointId
);
uuid_id!(
    /// A resource row within a checkpoint.
    ResourceId
);
uuid_id!(
    /// A browser profile source, generated by the extension per profile.
    SourceId
);

uuid_id!(
    /// One restore run: a user-approved plan being executed.
    RestoreRunId
);
uuid_id!(
    /// One action within a restore run.
    RestoreActionId
);
uuid_id!(
    /// One attempt at an action's side effect, recorded before it happens.
    AttemptId
);

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn new_ids_are_unique_v4() {
        let a = CheckpointId::new();
        let b = CheckpointId::new();
        assert_ne!(a, b);
        assert_eq!(a.as_uuid().get_version_num(), 4);
    }

    #[test]
    fn display_and_parse_round_trip() {
        let id = SessionId::new();
        let text = id.to_string();
        assert_eq!(text.len(), 36);
        assert_eq!(text, text.to_lowercase());
        assert_eq!(text.parse::<SessionId>().unwrap(), id);
    }

    #[test]
    fn serde_is_a_plain_string() {
        let id = WorkspaceId::new();
        assert_eq!(serde_json::to_string(&id).unwrap(), format!("\"{id}\""));
    }
}
